//! Slice 3: the status route and release instructions (v2 sha256
//! `a3d5220c…5ea0`). Fixtures are generated by `testkit` with published
//! test keys. Cases the official goldens cover (V6–V9, V12's first
//! new-epoch status, H.53's status pair) run in `golden`; these are the
//! rest: end-to-end execution, every strict-match failure, crash points,
//! fault classes, rate, floor, uncertain attempts, halts and resume.

use super::*;
use crate::canonical::sha256_tagged;
use crate::client::HttpResponse;
use crate::holder::ListOutcome;
use crate::obligations::PendingStatus;
use crate::purge::ObligationsRefused;
use crate::status::{
    HolderStateClaim, ReleaseOutcome, ReleaseStep, STATUS_NEW_KEY_SPACING_MS, StatusPending,
};
use crate::testkit::{Fault, Forced};
use crate::wire::ReportState;
use serde_json::{Map, Value, json};
use std::collections::BTreeSet;

const A: &str = "resAAAAAAAAAAAAAAAAAAAAA";
const B: &str = "resBBBBBBBBBBBBBBBBBBBBB";
const X: &str = "resXXXXXXXXXXXXXXXXXXXXX";

struct World {
    _dir: tempfile::TempDir,
    rig: Rig,
    b_holding: String,
    b_obligation: String,
    /// The two units of the never-listed resource X: unattributed.
    x_units: Vec<String>,
}

/// A held and listed `active` (2 units), B held and `terminating` (3
/// units), X held and never listed (2 units, unattributed).
fn world() -> World {
    let (dir, mut rig) = rig();
    rig.store.hold(PLAIN, A, true, 2);
    rig.store.hold(PLAIN, B, true, 3);
    rig.store.hold(PLAIN, X, true, 2);
    rig.purger.add(PLAIN, A, 2);
    rig.purger.add(PLAIN, B, 3);
    let x_units = rig.purger.add(PLAIN, X, 2);
    let (b_holding, b_obligation) = {
        let mut authority = rig.authority.state();
        authority.add_active(PLAIN, A);
        let holding = authority.add_active(PLAIN, B);
        let obligation = authority.retire(&holding);
        (holding, obligation)
    };
    applied(rig.relist());
    World {
        _dir: dir,
        rig,
        b_holding,
        b_obligation,
        x_units,
    }
}

/// B purged and its `incomplete` report accepted (X keeps it from
/// `complete`). Returns the digest of that report's exact bytes.
fn purged_and_reported(w: &mut World) -> String {
    let rig = &mut w.rig;
    rig.report().unwrap();
    rig.purge().unwrap();
    rig.report().unwrap();
    let last = accepted_reports(rig).pop().expect("a report");
    assert_eq!(last["state"], "incomplete");
    assert_eq!(last["counts"]["quarantined_unattributed"], 2);
    rig.authority
        .state()
        .accepted_digests
        .last()
        .cloned()
        .expect("its digest")
}

fn accepted_reports(rig: &Rig) -> Vec<Map<String, Value>> {
    rig.authority
        .state()
        .reports
        .iter()
        .filter(|(_, status)| *status == 200)
        .map(|(claims, _)| claims.clone())
        .collect()
}

fn statuses(rig: &Rig) -> Vec<(Map<String, Value>, u16)> {
    rig.authority.state().statuses.clone()
}

fn accepted_statuses(rig: &Rig) -> Vec<Map<String, Value>> {
    statuses(rig)
        .into_iter()
        .filter(|(_, status)| *status == 200)
        .map(|(claims, _)| claims)
        .collect()
}

fn release_deletions(rig: &Rig, instruction_id: &str) -> BTreeSet<String> {
    rig.purger
        .view()
        .deletions
        .iter()
        .filter(|(_, by)| by == instruction_id)
        .map(|(unit, _)| unit.clone())
        .collect()
}

fn step(rig: &mut Rig, instruction_id: &str) -> Option<ReleaseStep> {
    rig.holder()
        .state()
        .status
        .instructions
        .get(instruction_id)
        .map(|r| r.step)
}

fn pending_status(rig: &mut Rig) -> Option<StatusPending> {
    rig.holder().state().status.pending.clone()
}

fn forced(rig: &Rig, response: HttpResponse) {
    rig.authority
        .state()
        .forced
        .push_back(Forced::Response(response));
}

fn problem(rig: &Rig, status: u16, code: &str) {
    let response = rig.authority.state().problem_answer(status, code, None);
    forced(rig, response);
}

fn floor(rig: &mut Rig, obligation: &str) -> Option<ReportState> {
    let epoch = rig.holder().state().high_water.clone()?.epoch;
    rig.holder()
        .state()
        .obligations
        .channels
        .get(obligation)
        .and_then(|c| c.floor_in(&epoch))
}

fn epoch(rig: &mut Rig) -> String {
    rig.holder().state().high_water.clone().unwrap().epoch
}

/// Past the 60 s new-key spacing and any back-off.
fn later(rig: &Rig) {
    rig.advance(u64::try_from(STATUS_NEW_KEY_SPACING_MS).unwrap() + 1_000);
}

// ----------------------------------------------------- end to end (L1–L7)

#[test]
fn an_exact_release_deletes_exactly_the_bound_units_and_then_complete_follows() {
    let mut w = world();
    let digest = purged_and_reported(&mut w);
    let rig = &mut w.rig;
    let ins = rig.authority.state().issue_release(&digest, 2);
    // A unit that becomes unattributed after the report is not bound.
    let late = rig.purger.add_unattributable();
    applied(rig.relist());
    let pass = rig.release().unwrap();
    assert_eq!(
        (pass.evaluated, pass.reserved, pass.deleted, pass.executed),
        (1, 1, 2, 1),
        "{pass:?}"
    );
    let expected: BTreeSet<String> = w.x_units.iter().cloned().collect();
    assert_eq!(release_deletions(rig, &ins), expected);
    assert!(
        rig.purger.present(&late),
        "added after the report: untouched"
    );
    assert_eq!(rig.purger.present_of(PLAIN, A), 2);
    assert!(rig.purger.view().refused.is_empty());
    assert_eq!(step(rig, &ins), Some(ReleaseStep::Deleted));
    // The status reports `executed` with the new count and digest (L6).
    let summary = rig.status().unwrap();
    assert_eq!(summary.receipts, 1, "{summary:?}");
    let sent = accepted_statuses(rig).pop().unwrap();
    assert_eq!(sent["release_result"]["instruction_id"], ins.as_str());
    assert_eq!(sent["release_result"]["result"], "executed");
    assert_eq!(sent["quarantined_unattributed"], 1);
    assert_eq!(
        sent["release_result"]["observed_manifest_digest"],
        sent["quarantine_manifest_digest"]
    );
    assert_eq!(step(rig, &ins), Some(ReleaseStep::Done));
    assert_eq!(
        rig.authority.state().finalized.get(&ins).copied(),
        Some("executed")
    );
    assert!(!rig.authority.state().outstanding(&ins));
    assert!(codes(rig).contains(&"lifecycle_release_executed"));
    // A release of the late unit, bound to that status, clears the rest;
    // then B's `complete` follows.
    let status_digest = rig
        .authority
        .state()
        .accepted_digests
        .last()
        .cloned()
        .unwrap();
    let second = rig.authority.state().issue_release(&status_digest, 1);
    applied(rig.relist());
    assert_eq!(rig.release().unwrap().executed, 1);
    assert_eq!(release_deletions(rig, &second), BTreeSet::from([late]));
    later(rig);
    assert_eq!(rig.status().unwrap().receipts, 1);
    applied(rig.relist());
    rig.purge().unwrap();
    rig.report().unwrap();
    assert_eq!(floor(rig, &w.b_obligation), Some(ReportState::Complete));
    assert_eq!(
        rig.authority.state().obligation_state(&w.b_holding),
        "complete"
    );
    // Nothing else was ever deleted by a release.
    let view = rig.purger.view();
    assert_eq!(view.deletions.len(), 3 + 2 + 1);
    assert!(view.refused.is_empty());
}

// ------------------------------------------------- strict match (L2, G.5)

/// Every way the bound manifest can fail to match deletes nothing, and the
/// status reports `mismatch` with the holder's current manifest digest.
#[test]
fn any_difference_from_the_bound_manifest_is_a_mismatch_and_deletes_nothing() {
    type Setup = fn(&mut World, &str) -> (String, u64);
    let cases: [(&str, Setup); 6] = [
        ("no manifest for the digest", |_, _| {
            (format!("sha256:{}", "0".repeat(64)), 2)
        }),
        ("approved_count differs", |_, digest| (digest.to_owned(), 3)),
        ("a unit became attributed (listed active)", |w, digest| {
            w.rig.authority.state().add_active(PLAIN, X);
            (digest.to_owned(), 2)
        }),
        ("a unit is gone", |w, digest| {
            let gone = w.x_units[0].clone();
            w.rig.purger.view().units.get_mut(&gone).unwrap().present = false;
            (digest.to_owned(), 2)
        }),
        ("a unit is reserved elsewhere", |w, digest| {
            let unit = w.x_units[1].clone();
            let mut purger = w.rig.purger.clone();
            crate::store::ArtifactPurger::reserve(
                &mut purger,
                "ins_elsewhere000000000001",
                &[(
                    unit,
                    Some(crate::wire::ResourceKey {
                        kind: PLAIN.into(),
                        id: X.into(),
                    }),
                )]
                .into(),
            )
            .unwrap();
            (digest.to_owned(), 2)
        }),
        ("the manifest file was lost", |w, digest| {
            let key = w.rig.holder().state().status.manifests[digest].key.clone();
            std::fs::remove_file(w.rig.dir.join(format!("manifest.{key}.json"))).unwrap();
            (digest.to_owned(), 2)
        }),
    ];
    for (name, setup) in cases {
        let mut w = world();
        let digest = purged_and_reported(&mut w);
        let (bound, count) = setup(&mut w, &digest);
        let rig = &mut w.rig;
        let ins = rig.authority.state().issue_release(&bound, count);
        applied(rig.relist());
        let pass = rig.release().unwrap();
        assert_eq!((pass.mismatched, pass.deleted), (1, 0), "{name}: {pass:?}");
        assert_eq!(step(rig, &ins), Some(ReleaseStep::Mismatch), "{name}");
        assert!(release_deletions(rig, &ins).is_empty(), "{name}");
        assert!(
            !rig.purger.view().calls.contains(&"reserve") || name.contains("elsewhere"),
            "{name}: nothing reserved"
        );
        assert!(codes(rig).contains(&"lifecycle_release_mismatch"), "{name}");
        // The status carries the mismatch and the current digest.
        assert_eq!(rig.status().unwrap().receipts, 1, "{name}");
        let sent = accepted_statuses(rig).pop().unwrap();
        assert_eq!(sent["release_result"]["result"], "mismatch", "{name}");
        assert_eq!(
            sent["release_result"]["observed_manifest_digest"], sent["quarantine_manifest_digest"],
            "{name}"
        );
        assert_eq!(
            step(rig, &ins),
            Some(ReleaseStep::MismatchReported),
            "{name}"
        );
        assert_eq!(
            rig.authority.state().finalized.get(&ins).copied(),
            Some("superseded_mismatch"),
            "{name}"
        );
        // Never re-run: a later pass and a stale re-listing change nothing.
        let deletions = rig.purger.view().deletions.len();
        applied(rig.relist());
        rig.release().unwrap();
        assert_eq!(rig.purger.view().deletions.len(), deletions, "{name}");
    }
}

// ------------------------------------------- already done (L10), unknown kind

/// An instruction still listed after it was executed (or reported as a
/// mismatch) in this epoch is neither run nor reported again.
#[test]
fn l10_a_finished_instruction_still_listed_is_not_run_or_re_reported() {
    let mut w = world();
    let digest = purged_and_reported(&mut w);
    let rig = &mut w.rig;
    let ins = rig.authority.state().issue_release(&digest, 2);
    applied(rig.relist());
    rig.release().unwrap();
    assert_eq!(rig.status().unwrap().receipts, 1);
    assert_eq!(step(rig, &ins), Some(ReleaseStep::Done));
    // A stale list still carries it (same epoch).
    let entry = json!({
        "instruction_id": ins, "kind": "quarantine_release",
        "bound_report_digest": digest, "approved_count": 2, "issued_seq": 1,
    });
    rig.authority.state().instructions.push(entry);
    rig.authority.state().commit();
    applied(rig.relist());
    let calls = rig.purger.view().calls.len();
    let pass = rig.release().unwrap();
    assert_eq!((pass.evaluated, pass.deleted), (0, 0));
    assert!(!rig.purger.view().calls[calls..].contains(&"reserve"));
    later(rig);
    let before = statuses(rig).len();
    assert_eq!(
        rig.status().unwrap().sent,
        0,
        "carried in this epoch already"
    );
    assert_eq!(statuses(rig).len(), before);
}

#[test]
fn h35_an_unknown_instruction_kind_is_skipped_whole_and_never_executed() {
    let mut w = world();
    let digest = purged_and_reported(&mut w);
    let rig = &mut w.rig;
    rig.authority.state().instructions.push(json!({
        "kind": "future_release", "instruction_id": "ins_future00000000000000001",
        "bound_report_digest": digest, "approved_count": 2, "issued_seq": 1, "extra": [1],
    }));
    rig.authority.state().commit();
    let report = applied(rig.relist());
    assert_eq!(report.instructions, 0);
    assert!(codes(rig).contains(&"lifecycle_instruction_skipped"));
    let pass = rig.release().unwrap();
    assert_eq!(pass, crate::release::ReleaseSummary::default());
    assert!(rig.purger.view().deletions.len() == 3, "only B's purge");
    assert!(rig.holder().state().status.instructions.is_empty());
}

// ------------------------------------------------------ blocked (H.9)

/// A declined release blocks the obligation; the holder treats it as
/// `terminating`, deletes nothing unattributed and keeps reporting. A later
/// exact release executes, and a zero-count status unblocks it.
#[test]
fn h9_a_declined_release_blocks_and_authorizes_no_deletion() {
    let mut w = world();
    let digest = purged_and_reported(&mut w);
    let rig = &mut w.rig;
    assert_eq!(rig.status().unwrap().receipts, 1);
    rig.authority.state().decline(&[w.b_holding.as_str()]);
    applied(rig.relist());
    for _ in 0..3 {
        rig.purge().unwrap();
        rig.report().unwrap();
        rig.release().unwrap();
        later(rig);
        rig.status().unwrap();
    }
    assert!(w.x_units.iter().all(|u| rig.purger.present(u)));
    assert_eq!(rig.purger.view().deletions.len(), 3, "only B's own units");
    assert_eq!(
        rig.authority.state().obligation_state(&w.b_holding),
        "blocked"
    );
    assert_eq!(rig.gate().check(B), Err(crate::gate::Refusal::Tombstoned));
    // A later approval executes; the zero count unblocks.
    let ins = rig.authority.state().issue_release(&digest, 2);
    applied(rig.relist());
    assert_eq!(rig.release().unwrap().executed, 1);
    later(rig);
    assert_eq!(rig.status().unwrap().receipts, 1);
    assert_eq!(step(rig, &ins), Some(ReleaseStep::Done));
    assert_eq!(
        rig.authority.state().obligation_state(&w.b_holding),
        "quarantined"
    );
}

// ------------------------------------------------- reservations (L1, L9)

#[test]
fn a_reservation_the_purger_has_not_confirmed_holds_every_list_back() {
    let mut w = world();
    let digest = purged_and_reported(&mut w);
    let rig = &mut w.rig;
    let ins = rig.authority.state().issue_release(&digest, 2);
    applied(rig.relist());
    rig.purger.view().fail_reserve = true;
    let pass = rig.release().unwrap();
    assert_eq!((pass.reserved, pass.deleted), (0, 0));
    assert_eq!(step(rig, &ins), Some(ReleaseStep::Reserving));
    assert!(codes(rig).contains(&"lifecycle_release_step_failed"));
    assert_eq!(rig.relist(), ListOutcome::ReservationPending);
    // Across a restart too, until the purger confirms it.
    rig.restart().unwrap();
    assert_eq!(rig.relist(), ListOutcome::ReservationPending);
    assert_eq!(rig.honor().unwrap(), 0);
    rig.purger.view().fail_reserve = false;
    assert_eq!(rig.honor().unwrap(), 1);
    assert_eq!(step(rig, &ins), Some(ReleaseStep::Draining));
    applied(rig.relist());
    assert_eq!(rig.release().unwrap().executed, 1);
}

/// L9: units a release holds are never claimed by an obligation, even
/// when their resource becomes obligated; only the release deletes them.
#[test]
fn l9_reserved_units_are_never_claimed_by_an_obligation() {
    let mut w = world();
    let digest = purged_and_reported(&mut w);
    let rig = &mut w.rig;
    let ins = rig.authority.state().issue_release(&digest, 2);
    applied(rig.relist());
    // One unit is busy, so the release cannot finish yet.
    rig.purger
        .view()
        .units
        .get_mut(&w.x_units[0])
        .unwrap()
        .open_handles = 1;
    let pass = rig.release().unwrap();
    assert_eq!((pass.deleted, pass.waiting_on_handles), (1, 1));
    // X is now listed and retired: its obligation must not claim the unit.
    {
        let mut authority = rig.authority.state();
        let holding = authority.add_active(PLAIN, X);
        authority.retire(&holding);
    }
    applied(rig.relist());
    for _ in 0..2 {
        rig.purge().unwrap();
        rig.report().unwrap();
    }
    assert!(rig.purger.view().refused.is_empty());
    assert!(rig.purger.present(&w.x_units[0]));
    // The handle closes: only the release deletes it.
    rig.purger
        .view()
        .units
        .get_mut(&w.x_units[0])
        .unwrap()
        .open_handles = 0;
    assert_eq!(rig.release().unwrap().executed, 1);
    let expected: BTreeSet<String> = w.x_units.iter().cloned().collect();
    assert_eq!(release_deletions(rig, &ins), expected);
}

// --------------------------------------- crash at every durable release step

fn release_crash_case(faults: Vec<Fault>, crash_after: Option<usize>) {
    let mut w = world();
    let digest = purged_and_reported(&mut w);
    let rig = &mut w.rig;
    let ins = rig.authority.state().issue_release(&digest, 2);
    applied(rig.relist());
    let before = rig.purger.view().deletions.len();
    rig.io_faults.plan(faults.clone());
    rig.purger.view().crash_after_deletes = crash_after.map(|n| before + n);
    let _ = rig.release();
    // The process ends here with only what is durable.
    rig.io_faults.clear();
    rig.purger.view().crash_after_deletes = None;
    rig.restart().unwrap();
    let context = format!("{faults:?} crash_after={crash_after:?}");
    if rig.holder().reservation_pending() {
        assert_eq!(rig.relist(), ListOutcome::ReservationPending, "{context}");
        assert_eq!(rig.honor().unwrap(), 1, "{context}");
    }
    assert_eq!(
        rig.release(),
        Err(ObligationsRefused::NoListThisProcess),
        "{context}"
    );
    applied(rig.relist());
    for _ in 0..3 {
        rig.release().unwrap();
    }
    assert_eq!(step(rig, &ins), Some(ReleaseStep::Deleted), "{context}");
    let expected: BTreeSet<String> = w.x_units.iter().cloned().collect();
    assert_eq!(release_deletions(rig, &ins), expected, "{context}");
    let view = rig.purger.view();
    assert!(view.refused.is_empty(), "{context}: {:?}", view.refused);
    assert_eq!(view.deletions.len(), before + 2, "{context}");
    drop(view);
    assert_eq!(rig.purger.present_of(PLAIN, A), 2, "{context}");
    assert_eq!(rig.status().unwrap().receipts, 1, "{context}");
    assert_eq!(step(rig, &ins), Some(ReleaseStep::Done), "{context}");
}

#[test]
fn release_crashes_at_every_durable_step_resume_without_unapproved_deletion() {
    // W(reserving), W(draining), W(claimed), W(deleted units), W(deleted).
    for at in 0..5 {
        for fault in [Fault::BeforeRename, Fault::AfterRename] {
            let mut plan = vec![Fault::Pass; at];
            plan.push(fault);
            release_crash_case(plan, None);
        }
    }
    // A crash between deletions, after the claim and before it is recorded.
    for after in 0..2 {
        release_crash_case(Vec::new(), Some(after));
    }
}

// ------------------------------------------------- status: T4, ack checks

#[test]
fn t4_a_status_carries_the_census_and_its_receipt_opens_the_gate() {
    let mut w = world();
    let rig = &mut w.rig;
    let current = epoch(rig);
    assert!(rig.holder().arm_status_gate(&current));
    let summary = rig.status().unwrap();
    assert_eq!((summary.derived, summary.sent, summary.receipts), (1, 1, 1));
    let sent = accepted_statuses(rig).pop().unwrap();
    let mut members: Vec<&str> = sent.keys().map(String::as_str).collect();
    members.sort_unstable();
    assert_eq!(
        members,
        [
            "aud",
            "exp",
            "holder_state",
            "htu",
            "iat",
            "idempotency_key",
            "iss",
            "jti",
            "list_ref",
            "quarantine_manifest_digest",
            "quarantined_unattributed",
            "sub"
        ]
    );
    assert_eq!(sent["quarantined_unattributed"], 2);
    assert_eq!(sent["holder_state"], "ok");
    let state = rig.holder().state().clone();
    assert_eq!(state.obligations.status_gate.acked_epoch, Some(current));
    assert!(state.obligations.status_gate.open());
    let accepted = state.status.last_accepted.expect("accepted");
    assert_eq!(accepted.quarantined_unattributed, 2);
    assert!(state.status.pending.is_none());
    // Nothing changed: no new status.
    later(rig);
    assert_eq!(rig.status().unwrap().derived, 0);
}

/// Acks that verify but do not match the attempt, its body or the route's
/// closed member set are never receipts; three in a row halt the status.
#[test]
fn status_acks_are_verified_against_the_exact_attempt_and_body() {
    let mut w = world();
    let rig = &mut w.rig;
    rig.authority.state().drop_status_acks = 1;
    assert_eq!(rig.status().unwrap().sent, 1);
    let pending = pending_status(rig).expect("armed");
    assert_eq!(pending.status, PendingStatus::Armed);
    let genuine = rig.authority.state().status_receipts[&pending.key]
        .1
        .clone();
    let genuine_claims = crate::jws::parse(&genuine).unwrap().claims;
    type Tamper = fn(&mut Map<String, Value>);
    let tampers: [(&str, Tamper); 7] = [
        ("count", |c| {
            c.insert("accepted_quarantined_unattributed".into(), 3.into());
        }),
        ("manifest", |c| {
            c.insert("accepted_manifest_digest".into(), "qm1.other".into());
        }),
        ("holder_state", |c| {
            c.insert("accepted_holder_state".into(), "reset".into());
        }),
        ("report_digest", |c| {
            c.insert(
                "report_digest".into(),
                format!("sha256:{}", "1".repeat(64)).into(),
            );
        }),
        ("disposition without a release_result", |c| {
            c.insert("release_result_disposition".into(), "applied".into());
        }),
        ("unknown member", |c| {
            c.insert("receipt_label".into(), "confirmed".into());
        }),
        ("exp", |c| {
            c.insert("exp".into(), 1.into());
        }),
    ];
    let mut halted = false;
    for (name, tamper) in tampers {
        let mut claims = genuine_claims.clone();
        tamper(&mut claims);
        let ack = rig
            .authority
            .state()
            .sign_status_ack(&Value::Object(claims));
        let answer = rig.authority.state().status_ack_answer(&ack);
        let class = rig.holder().classify_status(&pending.key, Ok(answer));
        assert!(
            matches!(
                class,
                crate::report::Answer::Unverifiable | crate::report::Answer::Halted
            ),
            "{name}: {class:?}"
        );
        halted |= class == crate::report::Answer::Halted;
        if halted {
            break;
        }
    }
    assert!(halted, "three unverifiable acks halt the status");
    assert!(rig.holder().state().status.halted);
    assert!(codes(rig).contains(&"lifecycle_status_bug_halt"));
    assert!(rig.holder().state().status.last_accepted.is_none());
}

/// The same key is retried with fresh proofs and exempt from the rate
/// limit; the authority answers the original ack byte-identical.
#[test]
fn h4_3_a_retry_reuses_the_key_and_gets_the_original_ack() {
    let mut w = world();
    let rig = &mut w.rig;
    rig.authority.state().drop_status_acks = 1;
    let first = rig.status().unwrap();
    assert_eq!((first.sent, first.receipts, first.waiting), (1, 0, 0));
    let key = pending_status(rig).unwrap().key;
    let original = rig.authority.state().status_receipts[&key].1.clone();
    rig.advance(11_000);
    let second = rig.status().unwrap();
    assert_eq!((second.sent, second.receipts), (1, 1), "{second:?}");
    let all = statuses(rig);
    assert_eq!(all.len(), 2);
    assert!(
        all.iter()
            .all(|(c, s)| c["idempotency_key"] == key.as_str() && *s == 200)
    );
    assert_ne!(all[0].0["jti"], all[1].0["jti"]);
    let receipt = std::fs::read(rig.dir.join(format!("sreceipt.{key}.jws"))).unwrap();
    assert_eq!(receipt, original.as_bytes());
}

/// H.4.4: one new key per 60 s, retries exempt; `429` backs off for at
/// least `Retry-After`.
#[test]
fn h4_4_new_keys_are_spaced_by_sixty_seconds() {
    let mut w = world();
    let rig = &mut w.rig;
    assert_eq!(rig.status().unwrap().receipts, 1);
    rig.purger.add_unattributable();
    let summary = rig.status().unwrap();
    assert_eq!((summary.derived, summary.sent, summary.waiting), (1, 0, 1));
    rig.advance(30_000);
    assert_eq!(rig.status().unwrap().sent, 0);
    rig.advance(31_000);
    assert_eq!(rig.status().unwrap().receipts, 1);
    // A `429` from the authority backs off past its Retry-After.
    rig.purger.add_unattributable();
    later(rig);
    problem(rig, 429, "rate_limited");
    let summary = rig.status().unwrap();
    assert_eq!((summary.sent, summary.receipts), (1, 0));
    rig.advance(4_000);
    assert_eq!(rig.status().unwrap().sent, 0, "still backing off");
    rig.advance(10_000);
    assert_eq!(rig.status().unwrap().receipts, 1);
    // The authority's own rate check never refused a key (the forced `429`
    // above never reached it).
    assert!(statuses(rig).iter().all(|(_, s)| *s == 200));
}

/// T6d and H.4.2: `409 stale_list_ref` is a definitive refusal; the holder
/// relists and re-derives under a new key, never a halt.
#[test]
fn t6d_stale_list_ref_relists_then_re_derives() {
    let mut w = world();
    let rig = &mut w.rig;
    problem(rig, 409, "stale_list_ref");
    let summary = rig.status().unwrap();
    assert_eq!(summary.rejected, 1);
    let rejected = pending_status(rig).unwrap();
    assert_eq!(rejected.status, PendingStatus::Rejected);
    assert!(rejected.attempts.is_empty(), "resolved: never accepted");
    assert!(!rig.holder().state().status.halted);
    assert!(codes(rig).contains(&"lifecycle_status_rejected"));
    later(rig);
    assert_eq!(rig.status().unwrap().derived, 0, "relist first");
    applied(rig.relist());
    let summary = rig.status().unwrap();
    assert_eq!((summary.derived, summary.receipts), (1, 1));
    let accepted = accepted_statuses(rig).pop().unwrap();
    assert_ne!(accepted["idempotency_key"], rejected.key.as_str());
}

