#[test]
fn t6c_bug_answers_halt_the_status_and_release_the_gate() {
    for (status, code) in [
        (400, "invalid_request"),
        (413, "payload_too_large"),
        (409, "idempotency_conflict"),
    ] {
        let mut w = world();
        let rig = &mut w.rig;
        let current = epoch(rig);
        assert!(rig.holder().arm_status_gate(&current));
        let summary = rig.report().unwrap();
        assert_eq!((summary.sent, summary.waiting), (0, 1), "{code}: gate shut");
        problem(rig, status, code);
        assert_eq!(rig.status().unwrap().halted, 1, "{code}");
        let state = rig.holder().state().clone();
        assert!(state.status.halted, "{code}");
        assert!(state.obligations.status_gate.open(), "{code}: released");
        // Obligation reports proceed while the status waits.
        assert_eq!(rig.report().unwrap().receipts, 1, "{code}");
        // Never re-derived automatically, across a restart too.
        rig.restart().unwrap();
        applied(rig.relist());
        later(rig);
        let summary = rig.status().unwrap();
        assert_eq!((summary.derived, summary.sent), (0, 0), "{code}");
        assert!(
            rig.holder().state().obligations.status_gate.open(),
            "{code}"
        );
    }
}

#[test]
fn n5_resume_invalidates_the_halted_status_and_closes_the_gate_until_a_new_ack() {
    let mut w = world();
    let rig = &mut w.rig;
    let current = epoch(rig);
    assert!(rig.holder().arm_status_gate(&current));
    problem(rig, 400, "invalid_request");
    rig.status().unwrap();
    let halted = pending_status(rig).unwrap();
    assert!(!halted.attempts.is_empty(), "possibly sent");
    assert!(!rig.holder().resume_report(&w.b_obligation), "not halted");
    assert!(rig.holder().resume_status());
    let state = rig.holder().state().clone();
    assert!(!state.status.halted);
    assert_eq!(
        state.status.pending.as_ref().map(|p| p.status),
        Some(PendingStatus::Invalidated)
    );
    assert!(state.status.uncertain.contains_key(&halted.key));
    assert!(!state.obligations.status_gate.open(), "closed again");
    assert!(codes(rig).contains(&"lifecycle_status_resumed"));
    // Re-derived under a new key; a newer list lets it pass the uncertain
    // attempt; its current-epoch ack opens the gate.
    rig.authority.state().commit();
    applied(rig.relist());
    later(rig);
    let summary = rig.status().unwrap();
    assert_eq!(summary.receipts, 1, "{summary:?}");
    let last = accepted_statuses(rig).pop().unwrap();
    assert_ne!(last["idempotency_key"], halted.key.as_str());
    assert!(rig.holder().state().obligations.status_gate.open());
}

