// ------------------------------------------------ uncertain attempts (H.50)

/// A status that may have been accepted is never overtaken by a new one
/// citing the same list: it waits for a newer list (H.4.2 floor) or for the
/// attempt's deadline to pass page 0 (H.13), and a late receipt resolves it.
#[test]
fn h50_a_possibly_sent_status_is_not_overtaken_on_the_same_list() {
    let mut w = world();
    let rig = &mut w.rig;
    rig.authority.state().drop_status_acks = 1;
    assert_eq!(rig.status().unwrap().sent, 1);
    let k1 = pending_status(rig).unwrap();
    // The census moves: K1 is invalidated and becomes uncertain.
    rig.purger.add_unattributable();
    later(rig);
    let summary = rig.status().unwrap();
    assert_eq!(
        (summary.invalidated, summary.derived, summary.sent),
        (1, 1, 0)
    );
    assert!(summary.waiting > 0);
    assert!(rig.holder().state().status.uncertain.contains_key(&k1.key));
    // A late receipt for K1 resolves it (T7).
    let k1_ack = rig.authority.state().status_receipts[&k1.key].1.clone();
    let delayed = rig.authority.state().status_ack_answer(&k1_ack);
    rig.authority.state().deliveries[&k1.key].deliver(k1.key.clone(), delayed);
    let pass = rig.status().unwrap();
    assert_eq!((pass.sent, pass.receipts), (0, 1));
    assert!(rig.holder().state().status.uncertain.is_empty());
    assert!(rig.dir.join(format!("sreceipt.{}.jws", k1.key)).exists());
    assert_eq!(
        rig.holder()
            .state()
            .status
            .last_accepted
            .as_ref()
            .map(|a| a.key.clone()),
        Some(k1.key.clone())
    );
    // With nothing uncertain, K2 goes out.
    assert_eq!(rig.status().unwrap().receipts, 1);
}

#[test]
fn h50_page_zero_after_the_deadline_resolves_an_uncertain_status() {
    let mut w = world();
    let rig = &mut w.rig;
    rig.authority.state().drop_status_acks = 1;
    assert_eq!(rig.status().unwrap().sent, 1);
    let k1 = pending_status(rig).unwrap();
    let exp_s = k1.attempts[0].exp_s;
    rig.purger.add_unattributable();
    later(rig);
    rig.status().unwrap();
    assert!(rig.holder().state().status.uncertain.contains_key(&k1.key));
    // A list whose page 0 is at exactly D does not resolve it...
    rig.authority.state().drop_status_acks = 0;
    let to_d = (exp_s + crate::report::ABSENCE_BOUND_S) * 1000 - {
        use crate::clock::Clock;
        rig.clock.wall_ms()
    };
    rig.advance(u64::try_from(to_d).unwrap() - 5_000);
    applied(rig.relist());
    assert!(now_s(rig) <= exp_s + crate::report::ABSENCE_BOUND_S);
    assert!(rig.holder().state().status.uncertain.contains_key(&k1.key));
    // ...one strictly after D does.
    rig.advance(6_000);
    applied(rig.relist());
    assert!(rig.holder().state().status.uncertain.is_empty());
}

