/// M10: a `403` cancels a queued, unsent status; a possibly-sent one is
/// kept as uncertain.
#[test]
fn m10_a_403_cancels_the_unsent_status_and_keeps_a_sent_one_uncertain() {
    let mut w = world();
    let rig = &mut w.rig;
    assert_eq!(rig.status().unwrap().receipts, 1);
    rig.purger.add_unattributable();
    assert_eq!(rig.status().unwrap().waiting, 1, "spacing holds it");
    assert!(pending_status(rig).is_some());
    problem(rig, 403, "holder_not_authorized");
    assert_eq!(
        rig.relist(),
        ListOutcome::Failed(crate::client::FetchFailure::NotAuthorized)
    );
    assert!(pending_status(rig).is_none(), "cancelled before any byte");
    // A possibly-sent one survives as uncertain.
    let mut w = world();
    let rig = &mut w.rig;
    rig.authority.state().drop_status_acks = 1;
    rig.status().unwrap();
    let sent = pending_status(rig).unwrap();
    problem(rig, 403, "holder_not_authorized");
    rig.relist();
    assert!(
        rig.holder()
            .state()
            .status
            .uncertain
            .contains_key(&sent.key)
    );
    later(rig);
    assert_eq!(
        rig.status().unwrap(),
        crate::status::StatusSummary::default()
    );
}

